// ToolStripContainer's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/tool_strip_container.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks and,
// where C# lets a subclass rewrite the value, the protected virtual coerce
// hook), the compare and store, then the written hook (the touch, side
// effects and the change event, through the protected virtual
// on_<property>_changed() where Windows Forms has OnXChanged). A read is
// `(*control).x.read()`.

// Whether the top panel shows (Windows Forms' TopToolStripPanelVisible; default true). A hidden panel takes no room and shows none of its strips.
template <typename Declaring>
struct ToolStripContainerTopPanelVisibleCapability {
    PropertyCell<bool, ToolStripContainerTopPanelVisibleCapability<Declaring>> top_panel_visible{true};

    static void assign(ToolStripContainerTopPanelVisibleCapability& capability, bool incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.top_panel_visible), incoming);
        if (!capability.top_panel_visible.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.top_panel_visible));
    }
};

