// How far the pointer moves from a grip press before it drags (4 units; a host may set 1 to 64). A value outside that range throws std::out_of_range and changes nothing.
template <typename Declaring>
struct ToolStripContainerDragThresholdCapability {
    PropertyCell<double, ToolStripContainerDragThresholdCapability<Declaring>> drag_threshold{4.0};

    static void assign(ToolStripContainerDragThresholdCapability& capability, double incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.drag_threshold), incoming);
        if (!capability.drag_threshold.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.drag_threshold));
    }
};

// Every ToolStripContainer capability, in the order the declaring class takes them.
template <typename Declaring>
struct ToolStripContainerCapabilities : public ToolStripContainerTopPanelVisibleCapability<Declaring>,
                                        public ToolStripContainerBottomPanelVisibleCapability<Declaring>,
                                        public ToolStripContainerLeftPanelVisibleCapability<Declaring>,
                                        public ToolStripContainerRightPanelVisibleCapability<Declaring>,
                                        public ToolStripContainerDragThresholdCapability<Declaring> {};

